export function decide(input) {
  if (!input || typeof input !== "object") return { action: "retry" };
  if (input.diagnostic) return { action: "redacted", ...input.diagnostic };
  const e = input.error;
  if (!e) return { action: "invalid_input" };
  if (input.sideEffect === "unknown") return { action: "retry" };
  if (e.status === 401) return { action: "no_retry", reason: "authentication" };
  if (e.code === "invalid_request") return { action: "no_retry", reason: "invalid_request" };
  if (e.status === 429 && e.code === "rate_limit" && input.attemptsConsumed <= input.totalAttemptCap) {
    return { action: "retry", waitSeconds: Number(e.headers?.["retry-after"] || 0) };
  }
  return { action: "retry" };
}
