import assert from "node:assert/strict";
import { allCases } from "./fixtures.mjs";

const solutionPath = process.env.SOLUTION === "reference" ? "./reference-answer.mjs" : "./learner.mjs";
const { decide } = await import(solutionPath);

function invoke(testCase) {
  return Object.hasOwn(testCase, "input") ? decide(testCase.input) : decide(testCase);
}

const results = [];
for (const testCase of allCases) {
  let actual;
  let pass = false;
  try {
    actual = invoke(testCase);
    assert.deepStrictEqual(actual, testCase.expected);
    pass = true;
  } catch (error) {
    if (actual === undefined) actual = { threw: error?.message || String(error) };
  }
  results.push({ id: testCase.id, core: testCase.core === true, pass, actual, expected: testCase.expected });
}

const failedIds = results.filter(result => !result.pass).map(result => result.id);
const coreResults = results.filter(result => result.core);
const coreFailedIds = coreResults.filter(result => !result.pass).map(result => result.id);
const summary = {
  passed: results.filter(result => result.pass).length,
  failed: failedIds.length,
  total: results.length,
  failedIds,
  core: {
    passed: coreResults.filter(result => result.pass).length,
    failed: coreFailedIds.length,
    total: coreResults.length,
    failedIds: coreFailedIds
  }
};

console.log(JSON.stringify(summary));
for (const result of results) {
  if (!result.pass) console.log(JSON.stringify({ id: result.id, actual: result.actual, expected: result.expected }));
}
process.exitCode = failedIds.length === 0 ? 0 : 1;
