const quotaCodes = new Set([
  "insufficient_quota",
  "organization_spend_limit_exceeded",
  "project_spend_limit_exceeded",
  "organization_usage_limit_exceeded"
]);

function isRecord(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function parseRetryAfter(error) {
  const headers = error.headers;
  if (headers === undefined) return 0;
  if (!isRecord(headers)) return null;
  const raw = headers["retry-after"];
  if (raw === undefined) return 0;
  if (typeof raw !== "string" || !/^(?:0|[1-9]\d*)(?:\.\d+)?$/.test(raw)) return null;
  const seconds = Number(raw);
  return Number.isFinite(seconds) && seconds >= 0 ? seconds : null;
}

export function decide(input) {
  if (!isRecord(input)) return { action: "invalid_input" };

  if (Object.hasOwn(input, "diagnostic")) {
    const diagnostic = input.diagnostic;
    if (!isRecord(diagnostic)) return { action: "invalid_input" };
    if (Object.hasOwn(diagnostic, "status") && (!Number.isInteger(diagnostic.status) || diagnostic.status < 100 || diagnostic.status > 599)) {
      return { action: "invalid_input" };
    }
    if (Object.hasOwn(diagnostic, "code") && typeof diagnostic.code !== "string") return { action: "invalid_input" };
    if (Object.hasOwn(diagnostic, "xRequestId") && typeof diagnostic.xRequestId !== "string") return { action: "invalid_input" };
    const output = {
      action: "redacted",
      apiKey: "OMITTED",
      body: "OMITTED"
    };
    if (Object.hasOwn(diagnostic, "status")) output.status = diagnostic.status;
    if (Object.hasOwn(diagnostic, "code")) output.code = diagnostic.code;
    if (Object.hasOwn(diagnostic, "xRequestId")) output.xRequestId = diagnostic.xRequestId;
    return output;
  }

  const error = input.error;
  if (!isRecord(error) || !Number.isInteger(error.status)) return { action: "invalid_input" };
  if (error.code !== undefined && typeof error.code !== "string") return { action: "invalid_input" };
  if (error.type !== undefined && typeof error.type !== "string") return { action: "invalid_input" };

  if (!Number.isInteger(input.attemptsConsumed) || input.attemptsConsumed < 1 || !Number.isInteger(input.totalAttemptCap) || input.totalAttemptCap < 1) {
    return { action: "invalid_input", reason: "invalid_attempt_budget" };
  }

  if (input.sideEffect === "unknown") return { action: "reconcile" };
  if (error.status === 401) return { action: "no_retry", reason: "authentication" };
  if (error.code === "invalid_request" || error.type === "invalid_request_error") return { action: "no_retry", reason: "invalid_request" };
  if (error.status === 429 && (quotaCodes.has(error.code) || error.type === "insufficient_quota")) {
    return { action: "no_retry", reason: "quota_or_billing" };
  }

  const transientRate = error.status === 429 && (error.code === "rate_limit" || error.code === "slow_down");
  const transientServer = error.status === 500 || error.status === 503;
  if (transientRate || transientServer) {
    if (input.attemptsConsumed >= input.totalAttemptCap) return { action: "no_retry", reason: "attempt_cap" };
    const waitSeconds = parseRetryAfter(error);
    if (waitSeconds === null) return { action: "invalid_input", reason: "invalid_retry_after" };
    return { action: "retry", waitSeconds };
  }

  return { action: "no_retry", reason: "unclassified" };
}
